steps.solution:
n = 0
try:
    with open("todo.txt") as f:
        for line in f:
            n += 1
    print(f"Tasks loaded: {n}")
except FileNotFoundError:
    print("Starting a new list")
while True:
    print("1 Add · 2 View · 3 Quit")
    menu = input()
    if menu == "3":
        print("Bye!")
        break
    elif menu == "1":
        item = input()
        with open("todo.txt", "a") as f:
            f.write(item + "\n")
        print(f"Added: {item}")
    elif menu == "2":
        try:
            with open("todo.txt") as f:
                for line in f:
                    print("-", line.strip())
        except FileNotFoundError:
